// Shared course chrome; authored C readings and stable storage keys stay intact.
(()=>{
 const $=id=>document.getElementById(id),escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const button=$('course-menu-button'),row=document.createElement('section');row.className='course-navigation';row.innerHTML='<div class="course-location"><span id="course-control-slot"></span><span id="course-row-progress"></span><nav id="course-breadcrumbs" aria-label="Breadcrumb"></nav></div><div id="course-contents" hidden></div>';document.querySelector('main').before(row);$('course-control-slot').append(button);button.innerHTML='Course lessons '+materialSymbol('expand_more');button.setAttribute('aria-controls','course-contents');
 const star=document.querySelector('.github-star');star.textContent='Source';document.querySelector('.copyright-notice').append(star);const brand=document.querySelector('.brand');brand.lastElementChild.textContent='C Foundry';brand.lastElementChild.insertAdjacentHTML('beforeend','<small>C17 programming</small>');
 let selectedPart;
 function route(){const parts=location.hash.slice(2).split('/');const chapter=parts[0]==='chapter'?COURSE.chapters.find(c=>c.id===parts[1]):parts[0]==='lesson'?COURSE.chapters.find(c=>c.labs.includes(parts[1])):null;return {parts,chapter,topic:chapter?.topics.find(t=>t.id===parts[2])};}
 function close(){button.setAttribute('aria-expanded','false');$('course-contents').hidden=true;}
 function outline(){const current=route(),part=selectedPart??current.chapter?.part??0;const progress=lessonCompletion.total();$('course-row-progress').textContent=`${progress.done} / ${progress.available} complete`;
  $('course-contents').innerHTML=`<a href="#/course">Course overview</a><label for="outline-part">Course part</label><select id="outline-part">${COURSE.parts.map((name,i)=>`<option value="${i}" ${part===i?'selected':''}>${i+1}. ${escape(name)}</option>`).join('')}</select><div class="course-outline-grid">${COURSE.chapters.filter(c=>c.part===part).map(c=>`<section><h3><a href="#/chapter/${c.id}">${c.number}. ${escape(c.title)}</a></h3><ol>${c.topics.map(t=>{const id=c.id+'/'+t.id;return `<li><a href="#/chapter/${id}" ${location.hash==='#/chapter/'+id?'aria-current="page"':''}>${lessonCompletion.isDone(id)?materialSymbol('check'):''}<span>${escape(t.title)}</span></a></li>`;}).join('')}</ol></section>`).join('')}</div>`;
  $('outline-part').onchange=event=>{selectedPart=Number(event.target.value);outline();};
 }
 button.onclick=()=>{const opening=$('course-contents').hidden;button.setAttribute('aria-expanded',String(opening));$('course-contents').hidden=!opening;if(opening)outline();};
 row.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();button.focus();}});
 function destination(href){const parts=(href||'').replace(/^#\//,'').split('/');if(parts[0]==='chapter'){const c=COURSE.chapters.find(c=>c.id===parts[1]),t=c?.topics.find(t=>t.id===parts[2]);return t?.title||c?.title||'Course overview';}if(parts[0]==='lesson')return LESSONS.find(l=>l.id===parts[1])?.title||'Practice';return {'course':'Choose a lesson','workspace':'C workspace','linux':'Browser Linux'}[parts[0]]||'Course overview';}
 function resources(){for(const details of document.querySelectorAll('main .lesson-references')){
   const summary=details.querySelector(':scope > summary');const names=[...details.querySelectorAll(':scope > ul > li > a')].map(a=>a.textContent.replace('(new tab)','').trim());summary.innerHTML=materialSymbol('menu_book')+`<span><strong>References</strong><small>${escape(names.join(' · '))}</small></span>`+materialSymbol('chevron_right');details.classList.add('resource-row');
   const practice=details.parentElement.querySelector('.documentation-practice');if(practice){const section=document.createElement('section');section.className='documentation-practice';section.innerHTML='<h3>Try the documentation</h3>'+[...practice.children].filter(el=>el.tagName!=='SUMMARY').map(el=>el.outerHTML).join('');const consult=section.querySelector('p a');if(consult)consult.parentElement.textContent='Use the '+consult.textContent.replace('(new tab)','').trim()+' link above, then open Compare your answer.';details.append(section);practice.remove();}
  }}
 function prediction(){const host=document.querySelector('#inline-editor-host');if(!host)return;const id=location.hash;host.insertAdjacentHTML('beforebegin','<label class="prediction-label" for="course-prediction">Your prediction (optional)</label><textarea id="course-prediction" rows="2" placeholder="What do you expect the program to show?"></textarea>');const field=$('course-prediction');field.value=window.cFoundryApp.prediction(id);field.oninput=()=>window.cFoundryApp.savePrediction(id,field.value);}
 function render(){close();selectedPart=undefined;const {chapter,topic,parts}=route();row.hidden=parts[0]==='course';$('course-breadcrumbs').innerHTML=chapter?`<span aria-hidden="true">/</span><a href="#/chapter/${chapter.id}">${escape(chapter.title)}</a>${topic?`<span aria-hidden="true">/</span><span aria-current="page">${escape(topic.title)}</span>`:''}`:`<span aria-hidden="true">/</span><span aria-current="page">${escape(document.querySelector('main>section:not([hidden]) h1')?.textContent||'Course')}</span>`;
  outline();document.querySelector('main .reading-breadcrumb')?.remove();document.querySelector('main .chapter-controls')?.remove();resources();prediction();
  for(const label of document.querySelectorAll('.completion-control')){const text=[...label.childNodes].find(n=>n.nodeType===Node.TEXT_NODE);if(text)text.textContent=' Mark lesson complete';}
  for(const nav of document.querySelectorAll('main .page-navigation')){const links=[...nav.querySelectorAll('a')];if(parts[1]==='first-program'&&parts[2]==='1'&&links[0])links[0].setAttribute('href','#/course');links.forEach((link,i)=>{const href=link.getAttribute('href'),title=destination(href),old=link.textContent,label=href==='#/course'?'Course overview':/Start/.test(old)?'Start chapter':/^#\/chapter\/[^/]+$/.test(href)?(/Previous/.test(old)?'Previous chapter':'Chapter overview'):/Previous/.test(old)?'Previous lesson':'Next lesson';link.innerHTML=`<small>${label}</small><strong>${escape(title)}</strong>`;});}
  // Local source/fixture links follow the current document's immutable release.
  const id=document.querySelector('meta[name="gpu-release"]')?.content;if(id){const base=new URL(document.querySelector('meta[name="gpu-base"]').content,location.href);for(const el of document.querySelectorAll('main a[href]')){const href=el.getAttribute('href');if(!/^(?:#|[a-z]+:|\/)/.test(href))el.href=new URL(`releases/${id}/`+href.replace(/^\.\//,''),base);}}
 }
 addEventListener('c-foundry:route',render);addEventListener('lessoncompletionchange',outline);render();
})();
